<body>
  <!-- disable-default-loading -->
  <div id="preloadContainer" style="display:none; width:0; height:0; overflow:hidden;"></div>
  <div id="sfxContainer" style="display:none;"></div>

  <div id="galContainer" class="gal-container">
    <img id="backgroundLayer" class="background-layer" src="">
    <video id="videoBackgroundLayer" class="background-layer" loop muted playsinline></video>

    <img id="spriteLeftImg" class="character-sprite pos-left">
    <video id="spriteLeftVideo" class="character-sprite pos-left" loop muted playsinline></video>
    <img id="spriteCenterImg" class="character-sprite pos-center">
    <video id="spriteCenterVideo" class="character-sprite pos-center" loop muted playsinline></video>
    <img id="spriteRightImg" class="character-sprite pos-right">
    <video id="spriteRightVideo" class="character-sprite pos-right" loop muted playsinline></video>

    <div id="dialogueBox" class="dialog-box">
      <div id="speakerName" class="speaker-name"></div>
      <div id="dialogueText" class="dialogue-text"></div>
      <div id="blinkingStar" class="blinking-star">✦</div>
    </div>

    <div id="history-log-panel" class="history-log-panel panel"></div>
    <div id="status-panel" class="status-panel panel"></div>

    <div id="settings-panel" class="settings-panel panel">
        <div class="setting-item">
          <label for="bgm-volume">BGM音量:</label>
          <input type="range" id="bgm-volume" min="0" max="1" step="0.05" value="0.45">
        </div>
        <div class="setting-item">
          <label for="video-volume">音效大小:</label>
          <input type="range" id="video-volume" min="0" max="1" step="0.05" value="0.6">
        </div>
        <div class="setting-item">
          <label for="text-speed">文本速度:</label>
          <input type="range" id="text-speed" min="10" max="100" step="5" value="50">
        </div>
        <div class="setting-item">
          <label for="font-size">文字大小:</label>
          <input type="range" id="font-size" min="2.5" max="5.5" step="0.1" value="4.0">
        </div>
        <div class="setting-item">
            <label>文本颜色:</label>
            <div class="color-swatches">
                <div class="color-swatch" style="background-color: #FFFFFF;" data-color="#FFFFFF"></div>
                <div class="color-swatch active" style="background-color: #F0E68C;" data-color="#F0E68C"></div>
                <div class="color-swatch" style="background-color: #ADD8E6;" data-color="#ADD8E6"></div>
                <div class="color-swatch" style="background-color: #FFB6C1;" data-color="#FFB6C1"></div>
            </div>
        </div>
    </div>

    <div class="button-container">
        <button id="prev-button" class="prev-button ui-button"><span class="icon icon-prev"></span></button>
        <button id="auto-play-button" class="auto-play-button ui-button"><span class="icon icon-play"></span><span class="icon icon-pause"></span></button>
        <button id="history-button" class="history-button ui-button"><span class="icon icon-history"></span></button>
        <button id="settings-button" class="settings-button ui-button"><span class="icon icon-settings"></span></button>
        <button id="status-button" class="status-button ui-button"><span class="icon icon-status"></span></button>
        <button id="fullscreenBtn" class="ui-button"><span class="icon icon-fullscreen"></span></button>
    </div>

    <audio id="bgmPlayer" loop></audio>
  </div>

  <script>
    $(document).ready(function() {
        const state = {
            instanceId: 'gal-' + Date.now() + '-' + Math.random(),
            lines: [],
            currentPageIndex: -1,
            isAutoPlaying: false,
            autoPlayTimer: null,
            isTyping: false,
            typewriterTimeout: null,
            isPreloading: false,
            isClickLocked: false, // MODIFIED: Added click guard
            activeMediaElements: [],
            preloadedUrls: new Set(),
            lastMediaSrc: { background: null, left: null, center: null, right: null },
            sfxPlayers: [],
            settings: {
                bgmVolume: 0.45,
                videoVolume: 0.6,
                textSpeed: 50,
                fontSize: 4.0,
                textColor: '#F0E68C',
                autoPlayDelay: 2000
            }
        };
        let hasInteracted = false;

        const $galContainer = $('#galContainer');
        const $backgroundLayer = $('#backgroundLayer');
        const $videoBackgroundLayer = $('#videoBackgroundLayer');
        const $dialogueBox = $('#dialogueBox');
        const $speakerName = $('#speakerName');
        const $dialogueText = $('#dialogueText');
        const $blinkingStar = $('#blinkingStar');
        const $bgmPlayer = $('#bgmPlayer');
        const $sfxContainer = $('#sfxContainer');

        const $sprites = {
            left: { img: $('#spriteLeftImg'), video: $('#spriteLeftVideo') },
            center: { img: $('#spriteCenterImg'), video: $('#spriteCenterVideo') },
            right: { img: $('#spriteRightImg'), video: $('#spriteRightVideo') }
        };
        const allVideos = [$videoBackgroundLayer, $sprites.left.video, $sprites.center.video, $sprites.right.video];

        const $prevButton = $('#prev-button'), $autoPlayButton = $('#auto-play-button'),
              $historyButton = $('#history-button'), $settingsButton = $('#settings-button'),
              $statusButton = $('#status-button'), $fullscreenBtn = $('#fullscreenBtn');

        const $historyPanel = $('#history-log-panel'), $settingsPanel = $('#settings-panel'),
              $statusPanel = $('#status-panel');
        const $preloadContainer = $('#preloadContainer');

        const $bgmVolumeSlider = $('#bgm-volume'), $videoVolumeSlider = $('#video-volume'),
              $textSpeedSlider = $('#text-speed'), $fontSizeSlider = $('#font-size');

        const urlPrefix = "https://files.catbox.moe/";

        function extractAssetUrl(rawString) {
            if (!rawString) return '';
            const regex = /(https?:\/\/[^\s]+|[a-zA-Z0-9_-]{6,}\.(?:mp4|mpg|png|jpg|jpeg|gif|webp|mp3|ogg|wav|aac))/i;
            const match = rawString.match(regex);
            return match ? match[0] : '';
        }

        function addPrefixIfNeeded(filename) {
            if (!filename || typeof filename !== 'string' || filename.trim() === '') return '';
            if (filename.startsWith('http://') || filename.startsWith('https://') || filename.startsWith('data:')) return filename;
            return urlPrefix + filename;
        }

        function parseGalText(text) {
            const regex = /【([^|]*)\|([^|]*)\|([^|]*)(?:\|([^|]*))?(?:\|([^|]*))?】/g;
            const matches = [...text.matchAll(regex)];

            return matches.map(match => {
                return {
                    speaker: (match[1] || '').trim(),
                    background: extractAssetUrl(match[2] || ''),
                    text: (match[3] || '').replace(/^"|"$/g, '').trim(),
                    sprite: extractAssetUrl(match[4] || ''),
                    sfx: (match[5] || '').trim()
                };
            });
        }

        function stopTypewriter() {
            if (state.typewriterTimeout) clearTimeout(state.typewriterTimeout);
            state.isTyping = false;
            if (state.lines[state.currentPageIndex]) {
                $dialogueText.text(state.lines[state.currentPageIndex].text);
            }
        }

        function typewriter(text, callback) {
            stopTypewriter();
            state.isTyping = true;
            $dialogueText.text('');
            const dialogueElement = $dialogueText[0];
            let i = 0;
            const typingSpeed = 110 - state.settings.textSpeed;
            const type = () => {
                if (i < text.length) {
                    $dialogueText.append(text.charAt(i++));
                    dialogueElement.scrollTop = dialogueElement.scrollHeight;
                    state.typewriterTimeout = setTimeout(type, typingSpeed);
                } else {
                    state.isTyping = false;
                    if (callback) callback();
                }
            };
            type();
        }

        function preloadNextSceneAssets(pageIndex) {
            if (pageIndex < 0 || pageIndex >= state.lines.length) {
                return;
            }
            state.isPreloading = true;
            $blinkingStar.addClass('loading');

            const lineData = state.lines[pageIndex];
            const assetUrls = new Set();

            if (lineData.background) assetUrls.add(addPrefixIfNeeded(lineData.background));
            if (lineData.sprite) {
                lineData.sprite.split(',').forEach(s => {
                    const trimmed = s.trim();
                    if(trimmed) assetUrls.add(addPrefixIfNeeded(trimmed));
                });
            }

            const urlsToLoad = [...assetUrls].filter(url => url && !state.preloadedUrls.has(url));

            if (urlsToLoad.length === 0) {
                state.isPreloading = false;
                $blinkingStar.removeClass('loading');
                return;
            }

            const promises = urlsToLoad.map(url => {
                return new Promise((assetResolve) => {
                    const el = (url.toLowerCase().match(/\.(mp4|mpg|webm)$/)) ? document.createElement('video') : new Image();
                    el.onload = el.oncanplaythrough = () => {
                        state.preloadedUrls.add(url);
                        assetResolve();
                    };
                    el.onerror = () => {
                        console.error("Asset failed to preload:", url);
                        assetResolve(); // Resolve even on error to not block flow
                    };
                    el.src = url;
                });
            });

            Promise.all(promises).finally(() => {
                state.isPreloading = false;
                $blinkingStar.removeClass('loading');
            });
        }

        function managePlayback() {
            allVideos.forEach($video => {
                const videoElement = $video[0];
                const shouldBeActive = state.activeMediaElements.some(activeEl => activeEl[0] === videoElement);

                if (shouldBeActive) {
                    if (videoElement.paused) {
                        videoElement.play().catch(()=>{});
                    }
                } else {
                    if (!videoElement.paused) {
                       videoElement.pause();
                    }
                }
            });
        }

        function setSprite(position, url) {
            const spriteLayers = $sprites[position];
            if (!spriteLayers) return;

            const fullUrl = addPrefixIfNeeded(url);

            if (fullUrl && fullUrl === state.lastMediaSrc[position]) {
                return;
            }

            const { img, video } = spriteLayers;
            let activeElement = null;
            if (img.hasClass('visible')) activeElement = img;
            else if (video.hasClass('visible')) activeElement = video;

            if (activeElement) {
                activeElement.removeClass('visible');
            }

            state.activeMediaElements = state.activeMediaElements.filter(el => el[0] !== video[0]);

            if (!fullUrl) {
                state.lastMediaSrc[position] = null;
                return;
            }

            setTimeout(() => {
                const isVideo = fullUrl.toLowerCase().endsWith('.mp4') || fullUrl.toLowerCase().endsWith('.mpg');
                const newElement = isVideo ? video : img;
                const otherElement = isVideo ? img : video;

                otherElement.removeClass('visible').removeAttr('src');

                newElement.attr('src', fullUrl);
                if (isVideo) {
                    newElement[0].currentTime = 0;
                    state.activeMediaElements.push(newElement);
                }
                newElement.addClass('visible');
                managePlayback();

            }, activeElement ? 125 : 0);

            state.lastMediaSrc[position] = fullUrl;
        }

        function updateUI() {
            playSfx('');

            if (state.currentPageIndex < 0 || state.currentPageIndex >= state.lines.length) {
                managePlayback();
                return;
            }

            const lineData = state.lines[state.currentPageIndex];

            const newBgUrl = addPrefixIfNeeded(lineData.background);
            if (newBgUrl !== state.lastMediaSrc.background) {
                $backgroundLayer.removeClass('active').removeAttr('src');
                $videoBackgroundLayer.removeClass('active').removeAttr('src');
                state.activeMediaElements = state.activeMediaElements.filter(el => el[0] !== $videoBackgroundLayer[0]);

                if (newBgUrl) {
                    const isBgVideo = newBgUrl.toLowerCase().endsWith('.mp4') || newBgUrl.toLowerCase().endsWith('.mpg');
                    if (isBgVideo) {
                        $videoBackgroundLayer.attr('src', newBgUrl).addClass('active');
                        $videoBackgroundLayer[0].currentTime = 0;
                        state.activeMediaElements.push($videoBackgroundLayer);
                    } else {
                        $backgroundLayer.attr('src', newBgUrl).addClass('active');
                    }
                }
                state.lastMediaSrc.background = newBgUrl;
            }

            const spriteData = (lineData.sprite || "").split(',').map(s => s.trim());
            const [sprite1, sprite2] = spriteData;

            if (spriteData.length > 1) {
                setSprite('left', sprite1);
                setSprite('right', sprite2);
                setSprite('center', '');
            } else if (spriteData.length === 1 && sprite1) {
                setSprite('center', sprite1);
                setSprite('left', '');
                setSprite('right', '');
            } else {
                setSprite('left', '');
                setSprite('center', '');
                setSprite('right', '');
            }

            if (hasInteracted) {
                managePlayback();
            }
            playSfx(lineData.sfx);

            $speakerName.text(lineData.speaker || '旁白');
            typewriter(lineData.text, () => {
                if (state.isAutoPlaying) {
                   state.autoPlayTimer = setTimeout(advancePage, state.settings.autoPlayDelay);
                }
                preloadNextSceneAssets(state.currentPageIndex + 1);
            });
        }

        async function playSfx(sfxString) {
            state.sfxPlayers.forEach(player => {
                player.pause();
                player.removeAttribute('src');
            });
            state.sfxPlayers = [];
            $sfxContainer.empty();

            if (!sfxString || !hasInteracted) return;

            const allSfxFiles = sfxString.split('/').map(s => s.trim()).filter(Boolean);
            const aacFiles = allSfxFiles.filter(file => file.toLowerCase().endsWith('.aac'));
            const mp3Files = allSfxFiles.filter(file => file.toLowerCase().endsWith('.mp3'));

            const playMp3s = () => {
                mp3Files.forEach(file => {
                    const sfxUrl = addPrefixIfNeeded(file);
                    const player = new Audio(sfxUrl);
                    player.volume = state.settings.videoVolume;
                    player.loop = true;
                    player.play().catch(e => console.error("MP3 SFX play failed:", e));
                    $sfxContainer.append(player);
                    state.sfxPlayers.push(player);
                });
            };

            const playAacSequentially = async () => {
                for (const file of aacFiles) {
                    await new Promise(resolve => {
                        const sfxUrl = addPrefixIfNeeded(file);
                        const player = new Audio(sfxUrl);
                        player.volume = state.settings.videoVolume;
                        player.loop = false;

                        player.onended = resolve;
                        player.onerror = () => {
                            console.error("Sequential AAC SFX failed to play:", sfxUrl);
                            resolve();
                        };

                        player.play().catch(e => {
                            console.error("Sequential AAC SFX play() caught error:", e);
                            resolve();
                        });

                        $sfxContainer.append(player);
                        state.sfxPlayers.push(player);
                    });
                }
                playMp3s();
            };

            if (aacFiles.length > 0) {
                await playAacSequentially();
            } else {
                playMp3s();
            }
        }

        function advancePage() {
            if (state.isClickLocked) return; // MODIFIED: Click guard
            state.isClickLocked = true;
            setTimeout(() => { state.isClickLocked = false; }, 300); // Lock for 300ms

            if (state.isTyping) {
                stopTypewriter();
                return;
            }

            if (state.currentPageIndex < state.lines.length - 1) {
                state.currentPageIndex++;
                updateUI();
            } else if (state.isAutoPlaying) {
                toggleAutoPlay();
            }
        }

        function prevPage() {
            if (state.isClickLocked) return;
            state.isClickLocked = true;
            setTimeout(() => { state.isClickLocked = false; }, 300);

            if (state.isTyping) stopTypewriter();
            if (state.currentPageIndex > 0) {
                state.currentPageIndex--;
                updateUI();
            }
        }

        function setAutoPlayButtonState(isPlaying) {
            $autoPlayButton.toggleClass('state-pause', isPlaying).toggleClass('state-play', !isPlaying);
        }

        function toggleAutoPlay() {
            state.isAutoPlaying = !state.isAutoPlaying;
            setAutoPlayButtonState(state.isAutoPlaying);
            if (state.isAutoPlaying && !state.isTyping) {
                advancePage();
            } else {
                clearTimeout(state.autoPlayTimer);
            }
        }

        function activatePlayback() {
            if (hasInteracted) return;

            if (typeof eventEmit !== 'undefined') {
                eventEmit('gal_instance_played', state.instanceId);
            }

            hasInteracted = true;
            allVideos.forEach($video => $video.prop('muted', false));

            if ($bgmPlayer[0].src && $bgmPlayer[0].paused) {
                $bgmPlayer[0].play().catch(e => console.error("BGM play failed:", e));
            }
            managePlayback();

            const currentLine = state.lines[state.currentPageIndex];
            if (currentLine && currentLine.sfx) {
                playSfx(currentLine.sfx);
            }
        }

        function populateHistoryLog() {
            $historyPanel.empty();
            state.lines.forEach((line, index) => {
                const $entry = $('<div class="history-log-entry"></div>');
                $entry.append($('<span class="speaker"></span>').text((line.speaker || '旁白') + ':'));
                $entry.append($('<span class="text"></span>').text(line.text));
                const $teleportButton = $('<button class="teleport-button">跳转</button>').on('click', e => {
                    e.stopPropagation();
                    activatePlayback();
                    if (state.isTyping) stopTypewriter();
                    state.currentPageIndex = index;
                    updateUI();
                    $historyPanel.removeClass('visible');
                });
                $entry.append($teleportButton);
                $historyPanel.append($entry);
            });
        }

        function applySettings(settings) {
            state.settings = { ...state.settings, ...settings };
            $bgmVolumeSlider.val(state.settings.bgmVolume);
            $bgmPlayer[0].volume = state.settings.bgmVolume;
            $videoVolumeSlider.val(state.settings.videoVolume);
            allVideos.forEach($video => $video[0].volume = state.settings.videoVolume);
            state.sfxPlayers.forEach(player => player.volume = state.settings.videoVolume);
            $textSpeedSlider.val(state.settings.textSpeed);
            $fontSizeSlider.val(state.settings.fontSize);
            updateFontSizes();
            $dialogueText.css('color', state.settings.textColor);
            $('.color-swatch').removeClass('active');
            $(`.color-swatch[data-color="${state.settings.textColor}"]`).addClass('active');
        }

        function updateFontSizes() {
            const baseSize = parseFloat(state.settings.fontSize);
            if (document.fullscreenElement) {
                const fullscreenSpeakerSize = baseSize * 0.50;
                const fullscreenDialogueSize = baseSize * 0.50;
                $speakerName.css('font-size', fullscreenSpeakerSize + 'em');
                $dialogueText.css('font-size', fullscreenDialogueSize + 'em');
            } else {
                $speakerName.css('font-size', '3.6em');
                $dialogueText.css('font-size', baseSize + 'em');
            }
        }

        function initialize() {
            const dialogueContent = `$1`;
            const statusText = `$2`;
            const bgmFileRaw = `$3`;

            state.lines = parseGalText(dialogueContent);

            if (statusText && statusText.trim()) {
                $statusPanel.html(statusText.trim().replace(/\n/g, '<br>'));
            }

            if (bgmFileRaw && bgmFileRaw.trim()) {
                const cleanBgmFile = extractAssetUrl(bgmFileRaw.trim());
                const bgmUrl = addPrefixIfNeeded(cleanBgmFile);
                if (bgmUrl && $bgmPlayer[0].src !== bgmUrl) {
                    $bgmPlayer[0].src = bgmUrl;
                }
            }

            if (state.lines.length > 0) {
                state.currentPageIndex = 0;
                updateUI();
                preloadNextSceneAssets(1);
            } else {
                $dialogueText.text("[错误: 未找到有效对话或对话格式不正确]");
            }

            // MODIFIED: Simplified main click handler
            $galContainer.on('click', e => {
                if ($(e.target).closest('.ui-button, .panel, .button-container').length) return;
                activatePlayback();
                $('.panel').removeClass('visible');
                advancePage();
            });

            $prevButton.on('click', e => { e.stopPropagation(); activatePlayback(); prevPage(); });
            $autoPlayButton.on('click', e => { e.stopPropagation(); activatePlayback(); toggleAutoPlay(); });

            function togglePanel(panelToToggle) {
                $('.panel').not(panelToToggle).removeClass('visible');
                panelToToggle.toggleClass('visible');
            }

            $historyButton.on('click', e => {
                e.stopPropagation(); activatePlayback();
                togglePanel($historyPanel);
                if($historyPanel.hasClass('visible')) populateHistoryLog();
            });
            $settingsButton.on('click', e => {
                e.stopPropagation(); activatePlayback();
                togglePanel($settingsPanel);
            });
            $statusButton.on('click', e => {
                e.stopPropagation(); activatePlayback();
                togglePanel($statusPanel);
            });

            $fullscreenBtn.on('click', e => {
                e.stopPropagation();
                activatePlayback();

                if (!document.fullscreenElement) {
                    ($galContainer[0].requestFullscreen || $galContainer[0].webkitRequestFullscreen || $galContainer[0].msRequestFullscreen).call($galContainer[0]).catch(()=>{});
                } else {
                    document.exitFullscreen();
                }
            });

            document.addEventListener('fullscreenchange', () => {
                updateFontSizes();
                if (!document.fullscreenElement) {
                    setTimeout(() => {
                        window.parent.scrollTo({ top: window.parent.document.body.scrollHeight, behavior: 'smooth' });
                    }, 100);
                }
            });

            const settingsToSync = ['bgmVolume', 'videoVolume', 'textSpeed', 'fontSize', 'textColor'];
            function broadcastSettings() {
                if(typeof eventEmit === 'undefined') return;
                const currentSettings = {};
                settingsToSync.forEach(key => currentSettings[key] = state.settings[key]);
                eventEmit('gal_settings_updated', { senderId: state.instanceId, settings: currentSettings });
            }

            $bgmVolumeSlider.on('input', function() {
                state.settings.bgmVolume = $(this).val();
                $bgmPlayer[0].volume = state.settings.bgmVolume;
                broadcastSettings();
            }).val(state.settings.bgmVolume);

            $videoVolumeSlider.on('input', function() {
                const newVolume = $(this).val();
                state.settings.videoVolume = newVolume;
                allVideos.forEach($video => $video[0].volume = newVolume);
                state.sfxPlayers.forEach(player => player.volume = newVolume);
                broadcastSettings();
            }).val(state.settings.videoVolume);

            $textSpeedSlider.on('input', function() {
                state.settings.textSpeed = parseInt($(this).val());
                broadcastSettings();
            }).val(state.settings.textSpeed);

            $fontSizeSlider.on('input', function() {
                state.settings.fontSize = $(this).val();
                updateFontSizes();
                broadcastSettings();
            }).val(state.settings.fontSize);

            $('.color-swatch').on('click', function() {
                const newColor = $(this).data('color');
                state.settings.textColor = newColor;
                $dialogueText.css('color', newColor);
                $('.color-swatch').removeClass('active');
                $(this).addClass('active');
                broadcastSettings();
            });

            applySettings(state.settings);

            if(typeof eventOn !== 'undefined'){
                eventOn('gal_instance_played', (playedInstanceId) => {
                    if (state.instanceId !== playedInstanceId) {
                        $bgmPlayer[0].pause();
                        allVideos.forEach($video => $video[0].pause());
                        state.sfxPlayers.forEach(player => player.pause());
                    }
                });
                eventOn('gal_settings_updated', (payload) => {
                    if (payload && payload.senderId !== state.instanceId) {
                        applySettings(payload.settings);
                    }
                });
            }

            setTimeout(() => $dialogueBox.addClass('visible'), 100);
            setAutoPlayButtonState(state.isAutoPlaying);
        }

        initialize();
    });
  </script>
</body>
</html>
