                const character = this.dataset.char;
                const imageUrl = this.dataset.img;
                const display = document.getElementById(character + '-display');
                const displayImage = display.querySelector('img');

                document.querySelectorAll(`.wardrobe-btn[data-char="${character}"]`).forEach(btn => {
                    btn.classList.remove('active');
                });

                this.classList.add('active');
                displayImage.src = imageUrl;
            });
        });

        // Music player logic
        const bgm = document.getElementById('bgm');
        const musicControl = document.getElementById('music-control');

        function setButtonState(isPlaying) {
            if (isPlaying) {
                musicControl.classList.remove('paused');
                musicControl.classList.add('playing');
            } else {
                musicControl.classList.remove('playing');
                musicControl.classList.add('paused');
            }
        }

        function togglePlay() {
            if (bgm.paused) {
                bgm.play().catch(e => console.error("Audio play failed:", e));
            } else {
                bgm.pause();
            }
        }

        // Attempt to play on load and handle browser policies
        let playPromise = bgm.play();
        if (playPromise !== undefined) {
            playPromise.then(() => {
                // Autoplay started!
                setButtonState(true);
            }).catch(error => {
                // Autoplay was prevented.
                console.log("Autoplay prevented. Waiting for user interaction.");
                setButtonState(false);
            });
        }

        // Sync button state with audio element state
        bgm.onplay = () => setButtonState(true);
        bgm.onpause = () => setButtonState(false);

        musicControl.addEventListener('click', function(event) {
            event.stopPropagation();
            togglePlay();
        });
    });
</script>

